package redis

import (
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"os"

	goredis "github.com/redis/go-redis/v9"
	"go.flipt.io/flipt/internal/config"
)

// NewClient constructs a redis client from the provided configuration.
//
// When the configuration requests a TLS connection (require_tls), the client
// is configured to speak TLS 1.2 at the earliest and to trust either the
// certificate authority bundle supplied inline (ca_cert_bytes) or by path
// (ca_cert_path). When no bundle is supplied, the certificate authorities
// bundled with the host system are used. Verification of the servers
// certificate can be disabled entirely with insecure_skip_tls.
func NewClient(cfg config.RedisCacheConfig) (*goredis.Client, error) {
	opts := &goredis.Options{
		Addr:            fmt.Sprintf("%s:%d", cfg.Host, cfg.Port),
		Username:        cfg.Username,
		Password:        cfg.Password,
		DB:              cfg.DB,
		PoolSize:        cfg.PoolSize,
		MinIdleConns:    cfg.MinIdleConn,
		ConnMaxIdleTime: cfg.ConnMaxIdleTime,
		DialTimeout:     cfg.NetTimeout,
		ReadTimeout:     cfg.NetTimeout * 2,
		WriteTimeout:    cfg.NetTimeout * 2,
		PoolTimeout:     cfg.NetTimeout * 2,
	}

	if cfg.RequireTLS {
		tlsCfg, err := tlsConfig(cfg)
		if err != nil {
			return nil, err
		}

		opts.TLSConfig = tlsCfg
	}

	return goredis.NewClient(opts), nil
}

// tlsConfig builds the client configuration used to secure a connection to
// a TLS enabled redis server.
func tlsConfig(cfg config.RedisCacheConfig) (*tls.Config, error) {
	tlsCfg := &tls.Config{
		MinVersion:         tls.VersionTLS12,
		InsecureSkipVerify: cfg.InsecureSkipTLS,
	}

	bundle, err := caBundle(cfg)
	if err != nil {
		return nil, err
	}

	// without an explicit authority we let the client fall back to the
	// certificate authorities shipped with the host system.
	if len(bundle) == 0 {
		return tlsCfg, nil
	}

	pool, err := x509.SystemCertPool()
	if err != nil {
		return nil, fmt.Errorf("loading system certificate pool: %w", err)
	}

	if !pool.AppendCertsFromPEM(bundle) {
		return nil, errors.New("no certificates found in the provided ca_cert bundle")
	}

	tlsCfg.RootCAs = pool

	return tlsCfg, nil
}

// caBundle returns the certificate authority bundle to trust, preferring the
// inline configured bundle over one discovered on the filesystem.
func caBundle(cfg config.RedisCacheConfig) ([]byte, error) {
	if cfg.CaCertBytes != "" {
		return []byte(cfg.CaCertBytes), nil
	}

	if cfg.CaCertPath != "" {
		bundle, err := os.ReadFile(cfg.CaCertPath)
		if err != nil {
			return nil, fmt.Errorf("reading ca_cert_path: %w", err)
		}

		return bundle, nil
	}

	return nil, nil
}
